package org.telegram.ui;
import android.content.Context;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.telegram.messenger.*;
import org.telegram.messenger.music.*;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Components.*;
import static org.telegram.ui.Components.ClaudMusicStyle.*;

/** SoundCloud discovery, saved collections and a compact playback dock. */
public final class ClaudMusicActivity extends BaseFragment {
 private LinearLayout content,mini;private TextView miniTitle,miniArtist,miniArt;private ImageView miniPlay;private ProgressBar progress;private boolean active,dead,fetching;private String coverId="",genre="Lo-fi";private int generation;private String failure;
 private final HashMap<String,ArrayList<SoundCloudPublic.Playlist>> discovery=new HashMap<>();
 private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){if(!active)return;updateMini();handler.postDelayed(this,500);}};
 @Override public View createView(Context c){actionBar.setTitle("claud music");actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setBackgroundColor(BG);actionBar.setTitleColor(TEXT);actionBar.setItemsColor(TEXT,false);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){public void onItemClick(int id){if(id==-1)finishFragment();}});
  LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setBackgroundColor(BG);ScrollView scroll=new ScrollView(c);scroll.setVerticalScrollBarEnabled(false);content=new LinearLayout(c);content.setOrientation(1);content.setPadding(dp(22),dp(12),dp(22),dp(28));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout dock=new LinearLayout(c);dock.setOrientation(1);dock.setPadding(dp(12),0,dp(12),0);root.addView(dock);mini=new LinearLayout(c);mini.setOrientation(1);mini.setBackground(touch(SURFACE,16));dock.addView(mini,new LinearLayout.LayoutParams(-1,dp(70)));LinearLayout line=new LinearLayout(c);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(8),dp(7),dp(4),dp(5));mini.addView(line,new LinearLayout.LayoutParams(-1,0,1));miniArt=cover(c,9,null);line.addView(miniArt,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout labels=new LinearLayout(c);labels.setOrientation(1);labels.setPadding(dp(12),0,dp(8),0);line.addView(labels,new LinearLayout.LayoutParams(0,-2,1));miniTitle=text(c,"",14,true,TEXT);miniTitle.setSingleLine(true);miniTitle.setEllipsize(android.text.TextUtils.TruncateAt.END);miniArtist=text(c,"",12,false,MUTED);miniArtist.setPadding(0,dp(5),0,0);miniArtist.setSingleLine(true);labels.addView(miniTitle);labels.addView(miniArtist);labels.setOnClickListener(v->presentFragment(new ClaudSoundCloudPlayerActivity()));miniArt.setOnClickListener(v->presentFragment(new ClaudSoundCloudPlayerActivity()));miniPlay=icon(c,"play","Пауза или воспроизведение",TEXT,()->{SoundCloudPlayback.toggle();updateMini();});line.addView(miniPlay,new LinearLayout.LayoutParams(dp(48),dp(48)));progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(LINE));mini.addView(progress,new LinearLayout.LayoutParams(-1,dp(2)));
  LinearLayout nav=new LinearLayout(c);nav.setPadding(dp(12),dp(5),dp(12),dp(4));root.addView(nav,new LinearLayout.LayoutParams(-1,dp(72)));String[] names={"Главная","Поиск","Коллекция"},icons={"home","search","library"};for(int i=0;i<3;i++){final int tab=i;LinearLayout button=new LinearLayout(c);button.setOrientation(1);button.setGravity(Gravity.CENTER);nav.addView(button,new LinearLayout.LayoutParams(0,-1,1));ImageView mark=icon(c,icons[i],names[i],i==0?ACCENT:MUTED,null);mark.setPadding(dp(8),dp(6),dp(8),dp(6));button.addView(mark,new LinearLayout.LayoutParams(dp(40),dp(36)));TextView label=text(c,names[i],10,i==0,i==0?TEXT:MUTED);button.addView(label);Runnable go=()->{if(tab==1)presentFragment(new ClaudSoundCloudActivity(""));else if(tab==2)presentFragment(new ClaudSoundCloudBrowseActivity("library","","Коллекция"));else render();};button.setOnClickListener(v->go.run());mark.setOnClickListener(v->go.run());}
  fragmentView=root;render();updateMini();loadDiscovery();return root;
 }
 private void heading(String name,String action,Runnable click){Context c=content.getContext();LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(28),0,dp(16));content.addView(row);TextView title=text(c,name,23,true,TEXT);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));if(action!=null){TextView more=text(c,action,12,true,MUTED);more.setPadding(dp(12),dp(10),0,dp(10));row.addView(more);more.setOnClickListener(v->click.run());}}
 private void render(){if(content==null)return;Context c=content.getContext();content.removeAllViews();LinearLayout titleRow=new LinearLayout(c);titleRow.setGravity(Gravity.CENTER_VERTICAL);content.addView(titleRow);TextView title=text(c,"Музыка",34,true,TEXT);title.setGravity(Gravity.CENTER_VERTICAL);titleRow.addView(title,new LinearLayout.LayoutParams(0,dp(54),1));titleRow.addView(icon(c,"search","Поиск",TEXT,()->presentFragment(new ClaudSoundCloudActivity(""))),new LinearLayout.LayoutParams(dp(44),dp(44)));
  HorizontalScrollView chips=new HorizontalScrollView(c);chips.setHorizontalScrollBarEnabled(false);LinearLayout genres=new LinearLayout(c);chips.addView(genres);LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(-1,dp(54));cl.topMargin=dp(12);content.addView(chips,cl);String[] names={"Lo-fi","Хип-хоп","Электроника","Инди"};for(String name:names){TextView chip=text(c,name,13,true,name.equals(genre)?BG:MUTED);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(18),0,dp(18),0);chip.setBackground(touch(name.equals(genre)?TEXT:SURFACE,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(38));lp.rightMargin=dp(8);genres.addView(chip,lp);chip.setOnClickListener(v->{if(genre.equals(name))return;genre=name;++generation;fetching=false;failure=null;render();loadDiscovery();});}
  heading("Плейлисты","SoundCloud",()->presentFragment(new ClaudSoundCloudActivity(genre)));ArrayList<SoundCloudPublic.Playlist> lists=discovery.get(genre);
  if(lists==null){LinearLayout row=new LinearLayout(c);content.addView(row);for(int i=0;i<2;i++){TextView skeleton=cover(c,14,null);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(160),1);lp.rightMargin=i==0?dp(12):0;row.addView(skeleton,lp);}TextView state=text(c,failure==null?"Загрузка…":"Не удалось загрузить · повторить",13,false,MUTED);state.setPadding(0,dp(12),0,0);content.addView(state);state.setOnClickListener(v->loadDiscovery());}
  else if(lists.isEmpty()){TextView empty=text(c,"Плейлисты не найдены",14,false,MUTED);content.addView(empty);}
  else{HorizontalScrollView shelf=new HorizontalScrollView(c);shelf.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(c);shelf.addView(row);content.addView(shelf);for(int i=0;i<Math.min(10,lists.size());i++){SoundCloudPublic.Playlist p=lists.get(i);LinearLayout tile=new LinearLayout(c);tile.setOrientation(1);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(174),-2);lp.rightMargin=dp(14);row.addView(tile,lp);tile.addView(cover(c,14,p.artwork),new LinearLayout.LayoutParams(-1,dp(174)));TextView name=text(c,p.title,15,true,TEXT);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(0,dp(12),0,0);tile.addView(name);TextView author=text(c,p.owner,12,false,MUTED);author.setSingleLine(true);author.setPadding(0,dp(6),0,0);tile.addView(author);tile.setOnClickListener(v->presentFragment(new ClaudSoundCloudBrowseActivity("public",p.id,p.title)));}}
  heading("Коллекция","Все",()->presentFragment(new ClaudSoundCloudBrowseActivity("library","","Коллекция")));LinearLayout pair=null;int n=0;for(Map.Entry<String,String> e:SoundCloudLibrary.playlists(currentAccount).entrySet()){if(n>=4)break;if(n%2==0){pair=new LinearLayout(c);content.addView(pair);}String id=e.getKey(),name=e.getValue();ArrayList<SoundCloudPublic.Track> songs=SoundCloudLibrary.tracks(currentAccount,id);LinearLayout tile=new LinearLayout(c);tile.setOrientation(1);tile.setPadding(dp(14),dp(14),dp(14),dp(14));tile.setBackground(touch(SURFACE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,0,n%2==0?dp(10):0,dp(10));pair.addView(tile,lp);TextView image=cover(c,9,songs.isEmpty()?null:songs.get(0).artwork);tile.addView(image,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView label=text(c,name,15,true,TEXT);label.setPadding(0,dp(16),0,dp(6));label.setSingleLine(true);tile.addView(label);tile.addView(text(c,songs.size()+" треков",12,false,MUTED));tile.setOnClickListener(v->presentFragment(new ClaudSoundCloudBrowseActivity("local",id,name)));n++;}if(n%2==1)pair.addView(new View(c),new LinearLayout.LayoutParams(0,1,1));
  ArrayList<SoundCloudPublic.Artist> followed=SoundCloudLibrary.following(currentAccount);if(!followed.isEmpty()){heading("Артисты",null,null);HorizontalScrollView strip=new HorizontalScrollView(c);strip.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(c);strip.addView(row);content.addView(strip);for(SoundCloudPublic.Artist a:followed){LinearLayout tile=new LinearLayout(c);tile.setOrientation(1);tile.setGravity(Gravity.CENTER_HORIZONTAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(90),-2);lp.rightMargin=dp(14);row.addView(tile,lp);tile.addView(cover(c,45,a.avatar),new LinearLayout.LayoutParams(dp(82),dp(82)));TextView name=text(c,a.name,12,true,TEXT);name.setSingleLine(true);name.setPadding(0,dp(10),0,0);tile.addView(name);tile.setOnClickListener(v->presentFragment(new ClaudSoundCloudBrowseActivity("artist",a.id,a.name)));}}
  ArrayList<SoundCloudPublic.Track> q=SoundCloudPlayback.queueSnapshot();if(!q.isEmpty()){heading("В очереди",null,null);for(int i=0;i<Math.min(5,q.size());i++){SoundCloudPublic.Track t=q.get(i);LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));content.addView(row,new LinearLayout.LayoutParams(-1,dp(72)));row.addView(cover(c,9,t.artwork),new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout labels=new LinearLayout(c);labels.setOrientation(1);labels.setPadding(dp(14),0,0,0);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView name=text(c,t.title,15,true,TEXT);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(name);TextView by=text(c,t.artist,12,false,MUTED);by.setPadding(0,dp(5),0,0);labels.addView(by);row.addView(icon(c,"play","Воспроизвести",MUTED,()->play(c,q,t)),new LinearLayout.LayoutParams(dp(40),dp(40)));row.setOnClickListener(v->play(c,q,t));}}
 }
 private void play(Context c,ArrayList<SoundCloudPublic.Track> q,SoundCloudPublic.Track t){SoundCloudPlayback.play(c,q,t);presentFragment(new ClaudSoundCloudPlayerActivity());}
 private void loadDiscovery(){if(dead||fetching||discovery.containsKey(genre))return;fetching=true;failure=null;int request=generation;String selected=genre;String term=selected.equals("Хип-хоп")?"hip hop":selected.equals("Электроника")?"electronic":selected.equals("Инди")?"indie":"lofi";new Thread(()->{try{SoundCloudPublic.CatalogPage page=SoundCloudPublic.catalog("/search/playlists_without_albums",term,null);AndroidUtilities.runOnUIThread(()->{if(dead||request!=generation)return;fetching=false;discovery.put(selected,page.playlists);render();});}catch(Exception e){AndroidUtilities.runOnUIThread(()->{if(dead||request!=generation)return;fetching=false;failure="network";render();});}},"claud-music-discovery").start();}
 private void updateMini(){if(mini==null)return;SoundCloudPublic.Track t=SoundCloudPlayback.current;mini.setVisibility(t==null?View.GONE:View.VISIBLE);if(t==null)return;miniTitle.setText(t.title);miniArtist.setText(t.artist);miniPlay.setImageDrawable(new ClaudMusicIcon(SoundCloudPlayback.paused()?"play":"pause",TEXT));long duration=SoundCloudPlayback.duration();progress.setProgress(duration<=0?0:(int)Math.min(1000,SoundCloudPlayback.position()*1000/duration));if(!coverId.equals(t.id)){coverId=t.id;miniArt.setTag(null);miniArt.setBackground(new ClaudMusicStyle.Cover());SoundCloudArtwork.bind(miniArt,ClaudMusicStyle.large(t.artwork));}}
 @Override public void onResume(){super.onResume();render();active=true;handler.removeCallbacks(tick);handler.post(tick);}
 @Override public void onPause(){active=false;handler.removeCallbacks(tick);super.onPause();}
 @Override public void onFragmentDestroy(){dead=true;++generation;active=false;handler.removeCallbacks(tick);mini=null;content=null;super.onFragmentDestroy();}
}
